text:
Provider cliente para Next.js App Router. Sincroniza Lenis con el ticker de GSAP, actualiza ScrollTrigger y expone la instancia mediante contexto.

```tsx
// app/providers/lenis-provider.tsx
"use client";

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { usePathname } from "next/navigation";
import Lenis from "lenis";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

const LenisContext = createContext<Lenis | null>(null);

type LenisProviderProps = {
  children: ReactNode;
};

export function LenisProvider({ children }: LenisProviderProps) {
  const pathname = usePathname();
  const lenisRef = useRef<Lenis | null>(null);
  const firstPathRef = useRef(true);
  const [lenis, setLenis] = useState<Lenis | null>(null);

  useEffect(() => {
    const instance = new Lenis({
      autoRaf: false,
      lerp: 0.1,
      smoothWheel: true,
      syncTouch: false,
    });

    lenisRef.current = instance;
    setLenis(instance);

    const previousScrollRestoration = window.history.scrollRestoration;
    window.history.scrollRestoration = "manual";

    const updateScrollTrigger = () => {
      ScrollTrigger.update();
    };

    const tick = (time: number) => {
      // GSAP entrega segundos; Lenis espera milisegundos.
      instance.raf(time * 1000);
    };

    instance.on("scroll", updateScrollTrigger);
    gsap.ticker.add(tick);

    // Evita saltos cuando la pestaña vuelve del segundo plano.
    gsap.ticker.lagSmoothing(0);

    const refreshFrame = requestAnimationFrame(() => {
      ScrollTrigger.refresh();

      const hash = window.location.hash;

      if (hash) {
        instance.scrollTo(hash, { immediate: true });
      }
    });

    return () => {
      cancelAnimationFrame(refreshFrame);
      gsap.ticker.remove(tick);
      instance.off("scroll", updateScrollTrigger);
      instance.destroy();

      window.history.scrollRestoration = previousScrollRestoration;
      lenisRef.current = null;
      setLenis(null);
    };
  }, []);

  useEffect(() => {
    const instance = lenisRef.current;

    if (!instance) return;

    if (firstPathRef.current) {
      firstPathRef.current = false;
      return;
    }

    instance.scrollTo(0, { immediate: true });

    const refreshFrame = requestAnimationFrame(() => {
      ScrollTrigger.refresh();
    });

    return () => cancelAnimationFrame(refreshFrame);
  }, [pathname]);

  return (
    <LenisContext.Provider value={lenis}>
      {children}
    </LenisContext.Provider>
  );
}

export function useLenis() {
  return useContext(LenisContext);
}
```

Móntalo una sola vez en el layout raíz:

```tsx
// app/layout.tsx
import { LenisProvider } from "./providers/lenis-provider";

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="es">
      <body>
        <LenisProvider>{children}</LenisProvider>
      </body>
    </html>
  );
}
```

Desde cualquier componente cliente:

```tsx
const lenis = useLenis();

lenis?.scrollTo("#proyectos", {
  offset: -96,
  duration: 1.2,
});
```

Cada componente debe limpiar únicamente sus propios ScrollTriggers; no uses `ScrollTrigger.getAll().forEach(trigger => trigger.kill())` en su desmontaje.
